const LANG_MAP = {
  'portugues':'pt', 'português':'pt',
  'english':'en',
  'espanol':'es', 'español':'es',
  'francais':'fr', 'français':'fr',
  'deutsch':'de',
  'italiano':'it',
  'русский':'ru',
  'العربية':'ar'
};
function normalizeLang(idiomaRaw) {
  if (!idiomaRaw) return 'pt';
  const parte = String(idiomaRaw).split('-')[0].trim().toLowerCase();
  return LANG_MAP[parte] || 'pt';
}

const item = $json;
const lang = normalizeLang(item.idioma);
const nome = item.nome || '';
const clinicaNome = item.clinica_nome || 'nossa clinica';
const link = item.google_link;
const custom = String(item.mensagem_custom || '').trim();

let mensagem;
if (custom) {
  mensagem = custom
    .split('{nome}').join(nome)
    .split('{clinica}').join(clinicaNome)
    .split('{link}').join(link);
} else {
  const textos = {
    pt: `Ola, ${nome}! Obrigado por visitar a ${clinicaNome}. Se puder, deixe sua avaliacao no Google: ${link}`,
    es: `Hola, ${nome}! Gracias por visitar ${clinicaNome}. Si puedes, deja tu resena en Google: ${link}`,
    en: `Hi, ${nome}! Thank you for visiting ${clinicaNome}. If you have a moment, please leave us a Google review: ${link}`,
    fr: `Bonjour ${nome}! Merci d'avoir visite ${clinicaNome}. Si possible, laissez-nous un avis Google: ${link}`,
    de: `Hallo ${nome}! Danke fuer Ihren Besuch bei ${clinicaNome}. Bewerten Sie uns gerne auf Google: ${link}`,
    it: `Ciao ${nome}! Grazie per aver visitato ${clinicaNome}. Se puoi, lasciaci una recensione su Google: ${link}`,
    ru: `Здравствуйте, ${nome}! Спасибо за визит в ${clinicaNome}. Если можете, оставьте отзыв в Google: ${link}`,
    ar: `مرحبا ${nome}! شكرا لزيارتك ${clinicaNome}. اذا امكن، اترك تقييما على Google: ${link}`,
  };
  mensagem = textos[lang] || textos.pt;
}

return {
  json: {
    ...item,
    mensagem_montada: mensagem,
  }
};

function sanitizarTelefone(tel) {
  if (!tel) return null;
  const s = String(tel);
  if (s.length <= 4) return '*'.repeat(s.length);
  return s.slice(0, 4) + '*'.repeat(Math.max(0, s.length - 6)) + s.slice(-2);
}
const item = $json;
return {
  json: {
    tipo: 'pos_consulta_simulado',
    agendamento_id: item.agendamento_id,
    clinica_id: item.clinica_id,
    instancia: item.whatsapp_instancia || null,
    telefone_sanitizado: sanitizarTelefone(item.telefone),
    mensagem_montada: item.mensagem_montada,
  }
};

// Classificacao conservadora (mesmo espirito do workflow de lembretes, simplificado
// para 2 buckets: so 'sucesso' com key.id explicito marca o flag de idempotencia;
// qualquer outra coisa (rejeicao HTTP, timeout, ambiguo) NAO marca -> sera
// reavaliado no proximo ciclo (15min) enquanto pos_consulta_enviado continuar false.
const original = $('Montar Mensagem Deterministica').item.json;
const resp = $json;

let classificacao, keyId = null, motivo = null;

if (resp && resp.success === true && resp.data && resp.data.key && resp.data.key.id) {
  classificacao = 'sucesso';
  keyId = resp.data.key.id;
} else if (resp && resp.error !== undefined) {
  classificacao = 'nao_enviado';
  motivo = String(resp.error).slice(0, 300);
} else {
  classificacao = 'nao_enviado';
  motivo = 'resposta_sem_key_id_sem_erro_explicito';
}

return {
  json: {
    ...original,
    classificacao,
    key_id: keyId,
    motivo_evolution: motivo,
  }
};

function sanitizarTelefone(tel) {
  if (!tel) return null;
  const s = String(tel);
  if (s.length <= 4) return '*'.repeat(s.length);
  return s.slice(0, 4) + '*'.repeat(Math.max(0, s.length - 6)) + s.slice(-2);
}
const item = $('Classificar Resultado Evolution').item.json;
return {
  json: {
    tipo: 'pos_consulta_enviado_real',
    agendamento_id: item.agendamento_id,
    clinica_id: item.clinica_id,
    telefone_sanitizado: sanitizarTelefone(item.telefone),
    message_id: item.key_id,
  }
};

const item = $json;
return {
  json: {
    tipo: 'pos_consulta_nao_enviado',
